  if(!fromUrl){ const t=q.match(/[?&#]theatre=([01])\b/); if(t) fromUrl=(t[1]==='1'?'theatre':'natural'); }
  if(fromUrl){ try{ localStorage.setItem('aimdojo.skyTime', fromUrl); }catch(e){} return fromUrl; }
  try{ const v=localStorage.getItem('aimdojo.skyTime'); if(SKY_TIMES.indexOf(v)>=0) return v; }catch(e){}
